@@ -0,0 +1,31 @@
+import { AppError } from "../errors.js";
+import { isDate } from "../dates.js";
+import { parseCsv } from "./csv.js";
+import { importSales } from "../domain/sales.js";
+
+/** Parses and validates till CSV before atomically importing its sales. */
+export function importSalesCsv(store, text) {
+  if (typeof text !== "string") throw new AppError("bad_request", { reason: "csv must be text" });
+  const lines = text.split(/\r?\n/).map((line, index) => ({ line, row: index + 1 })).filter(({ line }) => line.trim());
+  const header = parseCsv(lines.shift()?.line ?? "")[0] ?? [];
+  const columns = ["ticket", "soldAt", "dishId", "qty"];
+  if (header.length !== 4 || columns.some((key) => !header.includes(key)))
+    throw new AppError("sales_row", { row: 1, reason: "expected ticket,soldAt,dishId,qty columns" });
+  const rows = lines.map(({ line, row }) => {
+    const fail = (reason) => { throw new AppError("sales_row", { row, reason }); };
+    if (!/^(?:[^",]*|"(?:[^"]|"")*")(?:,(?:[^",]*|"(?:[^"]|"")*"))*$/.test(line)) fail("invalid CSV");
+    const fields = parseCsv(line)[0];
+    if (fields.length !== 4) fail("expected four fields");
+    const values = Object.fromEntries(header.map((key, i) => [key, fields[i].trim()]));
+    const { ticket, soldAt } = values;
+    const dishId = Number(values.dishId);
+    const qty = Number(values.qty);
+    if (!ticket) fail("ticket is required");
+    if (!/^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|[+-]\d{2}:\d{2})$/.test(soldAt) ||
+        !Number.isFinite(Date.parse(soldAt)) || !isDate(soldAt.slice(0, 10))) fail("soldAt must be an ISO instant");
+    if (!Number.isSafeInteger(dishId) || dishId < 1) fail("invalid dishId");
+    if (!Number.isSafeInteger(qty) || qty < 1) fail("qty must be a positive whole number");
+    return { row, ticket, soldAt: new Date(soldAt).toISOString(), dishId, qty };
+  });
+  return importSales(store, rows);
+}
